47	// Free tier RPM limits by model (requests per minute)
48	const GEMINI_RPM_LIMITS: Record<GeminiModel, number> = {
49	  'gemini-2.5-flash-lite': 10,
50	  'gemini-2.5-flash': 10,
51	  'gemini-2.5-pro': 5,
52	  'gemini-2.0-flash': 15,
53	  'gemini-2.0-flash-lite': 30,
54	  'gemini-3-flash': 10,
55	  'gemini-3-flash-preview': 5,
56	};
