58	// Track last request time for rate limiting
59	let lastRequestTime = 0;
60	
61	// Context window limits (prevents O(N²) token cost growth)
62	const DEFAULT_MAX_CONTEXT_MESSAGES = 20;  // Maximum messages to keep in conversation history
63	const DEFAULT_MAX_ESTIMATED_TOKENS = 100000;  // ~100k tokens max context (safety limit)
64	
65	/**
66	 * Enforce RPM rate limit for Gemini free tier.
67	 * Waits the required time between requests based on model's RPM limit + 100ms safety buffer.
68	 * Skipped entirely if rate limiting is disabled (billing users with 1000+ RPM available).
69	 */
70	async function enforceRateLimitForModel(model: GeminiModel, rateLimitingEnabled: boolean): Promise<void> {
71	  // Skip rate limiting if disabled (billing users with 1000+ RPM)
72	  if (!rateLimitingEnabled) {
73	    return;
74	  }
75	
76	  const rpm = GEMINI_RPM_LIMITS[model] || 5;
77	  const minimumDelayMs = Math.ceil(60000 / rpm) + 100; // (60s / RPM) + 100ms safety buffer
78	
79	  const now = Date.now();
80	  const timeSinceLastRequest = now - lastRequestTime;
81	
82	  if (timeSinceLastRequest < minimumDelayMs) {
83	    const waitTime = minimumDelayMs - timeSinceLastRequest;
84	    logger.debug('SDK', `Rate limiting: waiting ${waitTime}ms before Gemini request`, { model, rpm });
85	    await new Promise(resolve => setTimeout(resolve, waitTime));
86	  }
87	
88	  lastRequestTime = Date.now();
89	}
